def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]

    # Check for all valid starting positions for the prefix
    for i in range(len(s) - len(prefix) - len(suffix) + 1):
        if s[i:i + len(prefix)] == prefix:
            # Check if the remaining part of s after prefix can end with suffix
            if s[i + len(prefix):].startswith(suffix):
                return True
    return False

