def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse right in even-indexed rows
            for j in range(len(grid[i])):
                if j % 2 == 0:
                    result.append(grid[i][j])
        else:
            # Traverse left in odd-indexed rows
            for j in range(len(grid[i]) - 1, -1, -1):
                if j % 2 == 0:
                    result.append(grid[i][j])
    return result

from collections import Counter

def findValidPair(s: str) -> str:
    count = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            a = int(s[i])
            b = int(s[i + 1])
            if count[s[i]] == a and count[s[i + 1]] == b:
                return s[i] + s[i + 1]
    return ""

