def sumOfGoodNumbers(nums: List[int], k: int) -> int:
    total_sum = 0
    n = len(nums)
    for i in range(n):
        is_good = True
        if i - k >= 0 and nums[i] <= nums[i - k]:
            is_good = False
        if i + k < n and nums[i] <= nums[i + k]:
            is_good = False
        if is_good:
            total_sum += nums[i]
    return total_sum

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    if k > n:
        return False
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if len(set(substring)) == 1:
            if (i == 0 or s[i - 1] != substring[0]) and (i + k == n or s[i + k] != substring[0]):
                return True
    return False

def hasSameDigits(s: str) -> bool:
    while len(s) > 2:
        s = ''.join(str((int(s[i]) + int(s[i + 1])) % 10) for i in range(len(s) - 1))
    return s[0] == s[1]

