import itertools

def totalNumbers(digits: List[int]) -> int:
    even_numbers = set()
    for digit in digits:
        if digit % 2 == 0:
            # Select the last digit as the even digit
            remaining_digits = digits.copy()
            remaining_digits.remove(digit)
            # Generate permutations of the remaining two digits
            for perm in itertools.permutations(remaining_digits, 2):
                if perm[0] != 0:  # Avoid leading zeros
                    even_numbers.add(perm[0] * 100 + perm[1] * 10 + digit)
    return len(even_numbers)

def maxContainers(n: int, w: int, maxWeight: int) -> int:
    total_cells = n * n
    max_containers_by_weight = maxWeight // w
    return min(total_cells, max_containers_by_weight)

from typing import List

def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    # dp[i] will store the length of the longest subsequence ending with absolute difference at least diff
    dp = [1] * n
    # Store the maximum length found
    max_length = 1
    # Check pairs to build the dp array
    for i in range(1, n):
        for j in range(i):
            diff1 = abs(nums[i] - nums[j])
            for k in range(j):
                diff2 = abs(nums[j] - nums[k])
                if diff1 >= diff2:
                    dp[i] = max(dp[i], dp[j] + 1)
        max_length = max(max_length, dp[i])
    return max_length

def calculateScore(s: str) -> int:
    # A dictionary to map each character to its mirror
    mirror_map = {chr(i): chr(219 - i) for i in range(97, 123)}
    marked = [False] * len(s)
    score = 0

    for i in range(len(s)):
        if marked[i]:
            continue
        for j in range(i - 1, -1, -1):
            if marked[j]:
                continue
            if s[j] == mirror_map[s[i]]:
                marked[i] = True
                marked[j] = True
                score += i - j
                break

    return score

from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # Initialize starting point

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k is the number of robbers neutralized
                if i == 0 and j == 0:
                    continue  # Skip the starting point
                current = -float('inf')
                if i > 0:
                    current = max(current, dp[i - 1][j][k])
                if j > 0:
                    current = max(current, dp[i][j - 1][k])
                if current == -float('inf'):
                    continue  # No previous valid paths
                if coins[i][j] < 0:  # Robber case
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], current + coins[i][j])
                    # No case for k == 0 since we can't neutralize  
                else:  # Coin case
                    dp[i][j][k] = max(dp[i][j][k], current + coins[i][j])

                # Consider using a neutralization on the robber if we have any left
                if coins[i][j] < 0 and k < 2:
                    dp[i][j][k + 1] = max(dp[i][j][k + 1], current)  # Neutralize the robber

    # Return the maximum coins that can be gathered considering up to 2 neutralizations
    return max(dp[m - 1][n - 1])

