def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    from collections import defaultdict, deque

    # Create a graph from edges
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Binary search for the minimum possible max weight
    left, right = 1, 10**6
    result = -1

    while left <= right:
        mid = (left + right) // 2

        # Create a filtered graph with the maximum weight `mid`
        filtered_graph = defaultdict(list)
        out_degree = [0] * n

        for u in range(n):
            for v, w in graph[u]:
                if w <= mid and out_degree[u] < threshold:
                    filtered_graph[u].append((v, w))
                    out_degree[u] += 1

        # Check if we can reach node 0 with this filtered graph
        visited = [False] * n
        queue = deque([0])
        visited[0] = True

        while queue:
            node = queue.popleft()
            for neighbor, weight in filtered_graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        if all(visited):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_timers = [0] * numberOfUsers

    for event in events:
        event_type = event[0]
        timestamp = int(event[1])

        # Update online status before processing the event
        for i in range(numberOfUsers):
            if not online_status[i] and timestamp >= offline_timers[i]:
                online_status[i] = True

        if event_type == 'OFFLINE':
            user_id = int(event[2])
            online_status[user_id] = False
            offline_timers[user_id] = timestamp + 60

        elif event_type == 'MESSAGE':
            mentions_string = event[2]

            if mentions_string == 'ALL':
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == 'HERE':
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                mentioned_ids = mentions_string.split()
                for mention in mentioned_ids:
                    user_id = int(mention[2:])  # Extract id<number>
                    mentions[user_id] += 1

    return mentions

from typing import List

def maxFreeTime(eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
    n = len(startTime)
    free_intervals = []

    # Calculate initial free time slots before and after meetings
    if startTime[0] > 0:
        free_intervals.append((0, startTime[0]))  # Free time before the first meeting
    for i in range(1, n):
        free_intervals.append((endTime[i - 1], startTime[i]))  # Free time between meetings
    if endTime[-1] < eventTime:
        free_intervals.append((endTime[-1], eventTime))  # Free time after the last meeting

    # Initialize max free time calculation
    max_free_time = 0

    # Calculate gaps between the meetings and how much free time can be created
    for i in range(n):
        # Current meeting occupies [startTime[i], endTime[i]]
        start_gap = endTime[i] if i == 0 else endTime[i-1]
        end_gap = startTime[i] if i < n else eventTime

        # Check the free time between these two meeting times
        free_time = end_gap - start_gap
        if free_time > 0:
            max_free_time += free_time

    # Adjust max_free_time considering we can move k meetings
    if k > 0:
        # Create a list of potential increases in free time by moving each meeting
        potential_gains = []
        for i in range(n):
            if i > 0:
                gain = startTime[i] - endTime[i-1]
                if gain > 0:
                    potential_gains.append(gain)
            if i < n - 1:
                gain = endTime[i+1] - startTime[i]
                if gain > 0:
                    potential_gains.append(gain)

        # Sort gains in descending order and get the k largest
        potential_gains.sort(reverse=True)
        max_free_time += sum(potential_gains[:k])

    return max_free_time
